-- ============================================================
-- 138 · Italiana: variantele capitolelor (ramificaţii frecvente)
--
-- Cerut pe 2026-11-25 (vezi migrarea 137). Pentru fiecare capitol, poziţiile
-- de după despărţirea de celelalte capitole în care adversarul face altă mutare
-- în cel puţin ~10% din partidele de 1000–1600 (Chess.com, rapid şi blitz),
-- verificate să nu fie rare la 400–1000 şi 1600–2300.
-- Continuarea: adversarul joacă mutarea cea mai frecventă la 1000–1600; tu,
-- cea mai jucată la 1600–2300 dintre cele aflate la cel mult 0,35 de mutarea
-- motorului (Stockfish, adâncime 18). 7 semi-mutări după despărţire.
-- Ordinea: după câte partide de 1000–1600 ajung în ramificaţie.
-- ============================================================

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 6…Nb6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d4 e5d4 c3d4 c5b6 e4e5 f6g4 h2h3 g4h6 d4d5 c6a5 c1g5","move_explanations":{"11":"Nb6 — adversarul nu mai dă şah pe b4, ci retrage nebunul. Pare prudent, dar îţi lasă centrul liber: pionii de pe d4 şi e4 pot porni înainte.","12":"e5 — ataci calul de pe f6 cu pionul şi câştigi spaţiu.","13":"Cg4 — calul sare înainte, cu gândul la f2.","14":"h3 — îl alungi imediat. De pe g4, calul nu mai are decât câmpul h6, pe marginea tablei.","15":"Ch6 — calul se retrage pe margine, de unde nu controlează nimic din centru.","16":"d5 — ataci şi al doilea cal. Pionii tăi împing piesele adversarului înapoi, una câte una.","17":"Ca5 — calul fuge şi atacă nebunul de pe c4.","18":"Ng5 — nu-ţi retragi nebunul: ataci dama. Adversarul trebuie să se ocupe întâi de ea."},"final_text":"Caii adversarului au ajuns pe marginea tablei, pe h6 şi a5, iar pionii tăi de pe d5 şi e5 îi ţin acolo. Ai un avantaj mare: salvează-ţi nebunul de pe c4, fă rocada şi scoate restul pieselor.","popularitate_niveluri":{"incepator":25.9,"intermediar":18.7,"avansat":7.1}},{"nume":"Dacă adversarul joacă 7…Cxe4","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d4 e5d4 c3d4 c5b4 c1d2 f6e4 d2b4 c6b4 c4f7 e8f7 d1b3 d7d5 b3b4","move_explanations":{"13":"Cxe4 — adversarul nu schimbă nebunii, ci ia pionul de pe e4. E răspunsul ascuţit, des întâlnit la orice nivel.","14":"Nxb4 — iei nebunul care îţi dădea şah.","15":"Cxb4 — calul ia înapoi. Adversarul are acum un pion în plus.","16":"Nxf7+ — sacrifici nebunul pe f7, ca să scoţi regele din adăpost.","17":"Rxf7 — regele ia nebunul.","18":"Db3+ — şah, care atacă în acelaşi timp calul de pe b4. Aşa îţi recuperezi piesa.","19":"d5 — adversarul acoperă şahul cu pionul şi deschide drum nebunului de pe c8.","20":"Dxb4 — iei calul. Materialul e din nou egal."},"final_text":"Materialul e egal, dar regele adversarului stă pe f7 şi nu mai poate face rocada. Tu încă o poţi face: scoate calul de pe b1 şi adu tura în centru, pe coloana e.","popularitate_niveluri":{"incepator":27.1,"intermediar":29.8,"avansat":33.2}},{"nume":"Dacă adversarul face rocada la mutarea 8","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d4 e5d4 c3d4 c5b4 c1d2 b4d2 b1d2 e8g8 e4e5 f6e8 e1g1 d7d6 f1e1 d6e5 d4e5","move_explanations":{"15":"Rocada adversarului: în loc să lovească în centru cu d5, îşi pune regele la adăpost.","16":"e5 — ataci calul de pe f6 cu pionul. Câştigi spaţiu, iar calul trebuie să plece.","17":"Ce8 — calul se retrage înapoi, pe e8.","18":"Rocada ta. Regele e la adăpost, iar tura de pe f1 poate veni pe e1.","19":"d6 — adversarul atacă pionul de pe e5, ca să-şi elibereze jocul.","20":"Te1 — aperi pionul de pe e5 cu tura şi ocupi coloana e.","21":"dxe5 — adversarul schimbă pionii.","22":"dxe5 — iei înapoi. Pionul de pe e5 îi ia calului câmpurile d6 şi f6, iar tu ai mai mult spaţiu."},"final_text":"Ai un pion puternic pe e5, care îi ţine calul de pe e8 în spate. Planul: calul de pe d2 vine spre e4, apoi te uiţi spre flancul regelui.","popularitate_niveluri":{"incepator":52.6,"intermediar":47.8,"avansat":28.3}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'A';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 5…h6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d3 h7h6 e1g1 d7d6 b2b4 c5b6 a2a4 a7a6 h2h3","move_explanations":{"9":"h6 — adversarul împinge pionul de pe h, ca nebunul tău de pe c1 să nu poată veni pe g5.","10":"Rocada ta. Nu te grăbeşti: poziţia e liniştită.","11":"d6 — adversarul îşi sprijină pionul de pe e5.","12":"b4 — ataci nebunul de pe c5 cu pionul şi câştigi spaţiu pe flancul damei.","13":"Nb6 — nebunul se retrage pe b6, de unde priveşte tot spre f2.","14":"a4 — ameninţi a5, care ar închide nebunul de pe b6.","15":"a6 — adversarul îi face nebunului loc pe a7, ca să nu fie prins.","16":"h3 — un pas mic, dar util: calul şi nebunul adversarului nu mai pot veni pe g4."},"final_text":"Ai spaţiu pe flancul damei, cu pionii de pe a4 şi b4 împinşi. Planul e cel din varianta principală: Cbd2, Te1 şi calul spre f1 şi g3.","popularitate_niveluri":{"incepator":9.8,"intermediar":18.4,"avansat":20.5}},{"nume":"Dacă adversarul joacă 6…Ng4","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d3 d7d6 e1g1 c8g4 h2h3 g4h5 b1d2 e8g8 f1e1 a7a6 d2f1","move_explanations":{"11":"Ng4 — adversarul leagă calul de pe f3 de damă.","12":"h3 — întrebi nebunul ce vrea: să ia calul sau să se retragă.","13":"Nh5 — nebunul se retrage pe h5 şi păstrează legătura.","14":"Cbd2 — scoţi calul şi pregăteşti drumul lui spre f1 şi g3.","15":"Rocada adversarului.","16":"Te1 — tura vine în centru şi apără pionul de pe e4. Câmpul f1 rămâne liber pentru cal.","17":"a6 — adversarul îi face nebunului de pe c5 retragere pe a7.","18":"Cf1 — calul porneşte spre g3, de unde va ataca nebunul de pe h5."},"final_text":"Urmează Cg3: calul atacă nebunul de pe h5 şi îl obligă să plece sau să se schimbe. Apoi ai mână liberă pe ambele flancuri.","popularitate_niveluri":{"incepator":38.2,"intermediar":37.8,"avansat":30.4}},{"nume":"Dacă adversarul joacă 7…Ng4","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d3 d7d6 e1g1 e8g8 f1e1 c8g4 b1d2 a7a6 d2f1 b7b5 c4b3 a6a5 h2h3","move_explanations":{"13":"Ng4 — adversarul leagă calul de pe f3 de damă.","14":"Cbd2 — scoţi calul şi te pregăteşti să-l duci spre f1.","15":"a6 — adversarul îi face nebunului de pe c5 retragere pe a7.","16":"Cf1 — calul porneşte spre g3.","17":"b5 — adversarul atacă nebunul de pe c4 cu pionul.","18":"Nb3 — nebunul se retrage pe b3 şi rămâne pe diagonala spre f7.","19":"a5 — adversarul împinge mai departe şi pregăteşte a4, ca să-ţi alunge din nou nebunul.","20":"h3 — întrebi nebunul de pe g4: să ia calul sau să se retragă."},"final_text":"Dacă nebunul ia calul, iei înapoi cu dama şi ai perechea de nebuni. Dacă se retrage, urmează Cg3. La a4, nebunul tău are retragere pe c2.","popularitate_niveluri":{"incepator":44.1,"intermediar":40.1,"avansat":30.6}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'D';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 5…Nc5","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 b2b4 c5b4 c2c3 b4c5 d2d4 e5d4 e1g1 d4c3 c4f7 e8f7 d1d5","move_explanations":{"9":"Nc5 — nebunul se retrage pe c5, de unde priveşte spre f2.","10":"d4 — loveşti imediat în centru: pionul atacă şi nebunul de pe c5, şi pionul de pe e5.","11":"exd4 — adversarul ia pionul.","12":"Rocada ta. Laşi pionul de pe c3 în priză: dezvoltarea contează mai mult acum.","13":"dxc3 — adversarul ia încă un pion, dar regele lui stă tot în centru.","14":"Nxf7+ — sacrifici nebunul pe f7, ca să scoţi regele afară.","15":"Rxf7 — regele ia.","16":"Dd5+ — şah, care atacă şi nebunul de pe c5. După ce regele se mută, îl iei şi îţi recuperezi piesa."},"final_text":"După ce iei nebunul de pe c5, regele adversarului rămâne fără rocadă, iar pionul de pe c3 îl poţi lua cu calul. Ai dat pioni, dar eşti mult mai dezvoltat.","popularitate_niveluri":{"incepator":75.1,"intermediar":51.3,"avansat":27.1}},{"nume":"Dacă adversarul joacă 4…Nb6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 b2b4 c5b6 c2c3 g8f6 d2d3 d7d6 a2a4 a7a6 e1g1","move_explanations":{"7":"Nb6 — adversarul refuză gambitul: nu ia pionul, ci retrage nebunul pe b6.","8":"c3 — aperi pionul de pe b4 şi pregăteşti d4.","9":"Cf6 — adversarul scoate calul şi atacă pionul de pe e4.","10":"d3 — aperi pionul de pe e4. Jocul devine liniştit, ca o Partidă Italiană obişnuită, dar cu pionul tău deja pe b4.","11":"d6 — adversarul îşi sprijină pionul de pe e5.","12":"a4 — ameninţi a5, care ar prinde nebunul de pe b6.","13":"a6 — adversarul îi face nebunului loc pe a7.","14":"Rocada ta. Ai spaţiu pe flancul damei şi o poziţie sănătoasă."},"final_text":"Pionii tăi de pe a4 şi b4 îţi dau spaţiu pe flancul damei. Planul: Cbd2, Te1 şi calul spre f1 şi g3, ca în Giuoco Pianissimo.","popularitate_niveluri":{"incepator":16.7,"intermediar":17.5,"avansat":11.9}},{"nume":"Dacă adversarul joacă 6…exd4","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 b2b4 c5b4 c2c3 b4a5 d2d4 e5d4 e1g1 d4c3 d1b3 d8e7 b1c3 a5c3 b3c3","move_explanations":{"11":"exd4 — adversarul ia pionul din centru.","12":"Rocada ta. Nu te grăbeşti să iei pionul înapoi.","13":"dxc3 — adversarul ia încă un pion.","14":"Db3 — dama atacă pionul de pe f7, împreună cu nebunul de pe c4.","15":"De7 — adversarul apără f7 cu dama.","16":"Cxc3 — iei pionul înapoi şi îţi dezvolţi calul.","17":"Nxc3 — adversarul ia calul cu nebunul.","18":"Dxc3 — iei nebunul cu dama."},"final_text":"Ai doi pioni mai puţin, dar ai perechea de nebuni şi eşti mult mai dezvoltat. Urmează Na3, care atacă dama de pe e7.","popularitate_niveluri":{"incepator":77,"intermediar":84.5,"avansat":80.5}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'E';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 4…h6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 g8f6 d2d3 h7h6 e1g1 f8c5 c2c3 d7d6 b2b4 c5b6 a2a4","move_explanations":{"7":"h6 — adversarul împiedică Cg5 şi Ng5 înainte să-şi scoată nebunul.","8":"Rocada ta.","9":"Nc5 — adversarul scoate nebunul pe c5.","10":"c3 — pregăteşti b4 şi d4 şi îi iei nebunului câmpul d4.","11":"d6 — adversarul îşi sprijină pionul de pe e5.","12":"b4 — ataci nebunul cu pionul şi câştigi spaţiu.","13":"Nb6 — nebunul se retrage pe b6.","14":"a4 — ameninţi a5, care ar prinde nebunul de pe b6."},"final_text":"Ai ajuns la aceeaşi aşezare ca în Giuoco Pianissimo: spaţiu pe flancul damei, cu pionii împinşi. Planul: Cbd2, Te1 şi calul spre f1 şi g3.","popularitate_niveluri":{"incepator":12.1,"intermediar":17.9,"avansat":14.6}},{"nume":"Dacă adversarul joacă 4…d5","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 g8f6 d2d3 d7d5 e4d5 f6d5 e1g1 c8g4 h2h3 g4h5 f1e1","move_explanations":{"7":"d5 — adversarul loveşte imediat în centru.","8":"exd5 — iei pionul.","9":"Cxd5 — adversarul ia înapoi cu calul.","10":"Rocada ta. Urmează Te1, care va ataca pionul de pe e5.","11":"Ng4 — adversarul leagă calul de pe f3 de damă.","12":"h3 — întrebi nebunul: să ia calul sau să se retragă.","13":"Nh5 — nebunul se retrage şi păstrează legătura.","14":"Te1 — tura atacă pionul de pe e5."},"final_text":"Tu ai făcut rocada, adversarul încă nu. Pune presiune pe pionul de pe e5 şi termină-ţi dezvoltarea cu Cbd2.","popularitate_niveluri":{"incepator":20.5,"intermediar":14.3,"avansat":7.7}},{"nume":"Dacă adversarul joacă 6…Ng4","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 g8f6 d2d3 f8c5 c2c3 d7d6 b1d2 c8g4 h2h3 g4h5 d2f1 e8g8 f1g3 h5g6 c1g5","move_explanations":{"11":"Ng4 — adversarul leagă calul de pe f3 de damă.","12":"h3 — întrebi nebunul ce vrea.","13":"Nh5 — nebunul se retrage şi păstrează legătura.","14":"Cf1 — calul porneşte spre g3, de unde va ataca nebunul.","15":"Rocada adversarului.","16":"Cg3 — calul atacă nebunul de pe h5.","17":"Ng6 — nebunul se retrage pe g6.","18":"Ng5 — acum tu legi calul de pe f6 de damă."},"final_text":"Acum tu eşti cel care leagă un cal. Regele tău stă încă în centru, deci urmează rocada.","popularitate_niveluri":{"incepator":35.5,"intermediar":33.3,"avansat":23}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'B';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 7…Ng4","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8e7 d2d3 d7d6 c2c3 g8f6 b1d2 e8g8 e1g1 c8g4 h2h3 g4h5 f1e1 a7a6 c4b3 b7b5 d2f1","move_explanations":{"13":"Ng4 — adversarul leagă calul de pe f3 de damă.","14":"h3 — întrebi nebunul ce vrea.","15":"Nh5 — nebunul se retrage şi păstrează legătura.","16":"Te1 — tura vine în centru, apără pionul de pe e4 şi eliberează f1 pentru cal.","17":"a6 — adversarul pregăteşte b5, ca să-ţi alunge nebunul.","18":"Nb3 — retragi nebunul înainte să fie atacat.","19":"b5 — adversarul câştigă spaţiu pe flancul damei.","20":"Cf1 — calul porneşte spre g3, de unde va ataca nebunul de pe h5."},"final_text":"Urmează Cg3, iar nebunul de pe h5 trebuie să plece. Pionii adversarului de pe a6 şi b5 pot deveni ţintă: a4 îi atacă.","popularitate_niveluri":{"incepator":29.6,"intermediar":29.1,"avansat":26.4}},{"nume":"Dacă adversarul joacă 7…Ca5","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8e7 d2d3 d7d6 c2c3 g8f6 b1d2 e8g8 e1g1 c6a5 c4b5 c7c6 b5a4 b7b5 a4c2 a5b7 f1e1","move_explanations":{"13":"Ca5 — calul atacă nebunul de pe c4, ca să-l schimbe.","14":"Nb5 — nu laşi schimbul: nebunul pleacă pe b5.","15":"c6 — adversarul alungă nebunul cu pionul.","16":"Na4 — nebunul se retrage pe a4 şi rămâne pe diagonală.","17":"b5 — adversarul îl atacă din nou.","18":"Nc2 — nebunul se retrage pe c2, unde e în siguranţă şi priveşte spre flancul regelui.","19":"Cb7 — calul de pe a5, rămas fără treabă, se întoarce spre centru.","20":"Te1 — tura vine în centru. Calul adversarului a pierdut timp cu plimbarea a5–b7."},"final_text":"Calul adversarului a făcut un ocol lung şi a ajuns pe b7, departe de centru, iar nebunul tău a scăpat de schimb. Planul obişnuit: Cf1, Cg3 şi d4.","popularitate_niveluri":{"incepator":14.3,"intermediar":18.6,"avansat":18.9}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'C';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 5…Cf6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 h7h6 d2d4 e5d4 e1g1 g8f6 e4e5 f6g4 h2h3 g4e5 f3e5 c6e5 f1e1","move_explanations":{"9":"Cf6 — adversarul scoate calul şi atacă pionul de pe e4.","10":"e5 — ataci calul cu pionul.","11":"Cg4 — calul sare pe g4.","12":"h3 — îl alungi.","13":"Cgxe5 — calul ia pionul de pe e5.","14":"Cxe5 — iei calul.","15":"Cxe5 — adversarul ia înapoi cu celălalt cal.","16":"Te1 — tura leagă calul de pe e5 de regele de pe e8."},"final_text":"Calul de pe e5 nu se poate mişca fără să lase regele în şah. Cu f4 îl ataci încă o dată şi câştigi o piesă.","popularitate_niveluri":{"incepator":27.6,"intermediar":20.4,"avansat":15.7}},{"nume":"Dacă adversarul joacă 5…d6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 h7h6 d2d4 e5d4 e1g1 d7d6 f3d4 c6d4 d1d4 g8f6 e4e5 d6e5 c4f7","move_explanations":{"9":"d6 — adversarul deschide drum nebunului de pe c8.","10":"Cxd4 — iei înapoi pionul de pe d4.","11":"Cxd4 — adversarul schimbă caii.","12":"Dxd4 — iei cu dama. Ai pionul înapoi şi o damă puternică în centru.","13":"Cf6 — adversarul scoate calul.","14":"e5 — ataci calul cu pionul.","15":"dxe5 — adversarul ia pionul, iar pionul nou de pe e5 îţi atacă dama.","16":"Nxf7+ — şah înainte de orice. Dacă regele ia nebunul, dama ta ia dama de pe d8. Dacă fuge pe e7, schimbi damele şi rămâi cu pionul de pe f7 câştigat."},"final_text":"Ai câştigat cel puţin un pion, iar regele adversarului a rămas fără rocadă.","popularitate_niveluri":{"incepator":15.1,"intermediar":19.6,"avansat":26.5}},{"nume":"Dacă adversarul joacă 8…Rf8","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 h7h6 d2d4 e5d4 e1g1 f8c5 c2c3 d4c3 c4f7 e8f7 d1d5 f7f8 d5c5 d7d6 c5c3 g8f6 f1e1 c8g4 b1d2","move_explanations":{"15":"Rf8 — regele fuge pe f8, nu pe e8.","16":"Dxc5+ — iei nebunul de pe c5 cu şah.","17":"d6 — adversarul acoperă şahul cu pionul.","18":"Dxc3 — dama se întoarce şi ia pionul de pe c3. Ai recuperat tot materialul.","19":"Cf6 — adversarul scoate calul.","20":"Te1 — tura ocupă coloana e şi apără pionul de pe e4.","21":"Ng4 — nebunul atacă calul de pe f3.","22":"Cbd2 — aperi calul cu celălalt cal şi îţi termini dezvoltarea."},"final_text":"Materialul e egal, dar regele adversarului a rămas fără rocadă pe f8, iar tura de pe h8 e închisă. Tu ai toate piesele gata de joc.","popularitate_niveluri":{"incepator":17.2,"intermediar":20.7,"avansat":27.6}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'P1';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 4…Cf6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 d7d6 c2c3 g8f6 f3g5 d6d5 e4d5 f6d5 d2d4 f8e7 g5f7","move_explanations":{"7":"Cf6 — adversarul scoate calul şi atacă pionul de pe e4.","8":"Cg5 — ataci pionul de pe f7 de două ori, cu calul şi cu nebunul.","9":"d5 — adversarul închide cu pionul diagonala nebunului tău.","10":"exd5 — iei pionul.","11":"Cxd5 — adversarul ia înapoi cu calul.","12":"d4 — loveşti în centru: pionul de pe e5 e atacat, iar diagonala nebunului de pe c1 se deschide.","13":"Ne7 — adversarul scoate nebunul şi îşi pregăteşte rocada.","14":"Cxf7 — sacrifici calul pe f7! Calul de pe d5 e legat de regele adversarului de nebunul tău de pe c4."},"final_text":"După Rxf7 vine Df3+: regele trebuie să se mute, iar calul legat de pe d5 cade."},{"nume":"Dacă adversarul joacă 5…Ch6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 d7d6 c2c3 c8g4 d1b3 g8h6 b3b7 c6a5 c4b5 c7c6 b5c6 a5c6 b7c6","move_explanations":{"9":"Ch6 — adversarul apără f7 cu calul, dar uită de pionul de pe b7.","10":"Dxb7 — iei pionul de pe b7 şi ataci calul de pe c6.","11":"Ca5 — calul fuge şi atacă dama şi nebunul de pe c4.","12":"Nb5+ — şah! Nebunul iese din atac cu tempo.","13":"c6 — adversarul acoperă şahul cu pionul.","14":"Nxc6+ — iei pionul cu şah.","15":"Cxc6 — calul ia nebunul.","16":"Dxc6+ — dama ia calul cu şah."},"final_text":"Ai doi pioni în plus şi o damă activă. Termină-ţi dezvoltarea şi fă rocada înainte de orice altceva.","popularitate_niveluri":{"incepator":16.3,"intermediar":13.5,"avansat":10.3}},{"nume":"Dacă adversarul joacă 7…Nxf3","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 d7d6 c2c3 c8g4 d1b3 d8d7 b3b7 a8b8 b7a6 g4f3 g2f3 g8f6 c4b5 b8b6 a6a4 f8e7 d2d3","move_explanations":{"13":"Nxf3 — adversarul schimbă nebunul pe calul tău, ca să-ţi strice pionii.","14":"gxf3 — iei înapoi cu pionul. Ai pionii dublaţi, dar şi perechea de nebuni şi un pion în plus.","15":"Cf6 — adversarul scoate calul.","16":"Nb5 — legi calul de pe c6 de dama de pe d7.","17":"Tb6 — tura atacă dama ta.","18":"Da4 — dama se retrage pe a4, de unde îşi apără nebunul.","19":"Ne7 — adversarul îşi scoate nebunul, ca să poată face rocada.","20":"d3 — deschizi drum nebunului de pe c1."},"final_text":"Ai un pion în plus şi perechea de nebuni. Planul: Ne3 şi Cd2, apoi rocada.","popularitate_niveluri":{"incepator":41.9,"intermediar":41,"avansat":42.6}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'P2';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 5…Nc5","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 c6d4 f3d4 e5d4 e1g1 f8c5 c4f7 e8f7 d1h5 g7g6 h5c5 d7d6 c5d4","move_explanations":{"9":"Nc5 — adversarul scoate nebunul şi apără pionul de pe d4.","10":"Nxf7+ — sacrifici nebunul pe f7. Dacă regele îl ia, dama ta intră în joc cu şah.","11":"Rxf7 — regele ia.","12":"Dh5+ — şah, care atacă în acelaşi timp nebunul de pe c5.","13":"g6 — adversarul acoperă şahul cu pionul. Nebunul de pe c5 rămâne neapărat.","14":"Dxc5 — iei nebunul. Ai recuperat piesa şi ai un pion în plus.","15":"d6 — adversarul atacă dama cu pionul.","16":"Dxd4 — dama ia pionul de pe d4."},"final_text":"Ai doi pioni în plus, iar regele adversarului a rămas pe f7, fără adăpost. Scoate-ţi piesele şi adu tura pe coloana f.","popularitate_niveluri":{"incepator":22.3,"intermediar":25.9,"avansat":20}},{"nume":"Dacă adversarul joacă 5…Cf6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 c6d4 f3d4 e5d4 e1g1 g8f6 d2d3 d7d6 c2c3 d4c3 d1b3 d8e7 b1c3","move_explanations":{"9":"Cf6 — adversarul scoate calul şi atacă pionul de pe e4.","10":"d3 — aperi pionul de pe e4 şi deschizi drum nebunului de pe c1.","11":"d6 — adversarul îşi deschide drum nebunului de pe c8.","12":"c3 — ataci pionul de pe d4, rămas singur în tabăra ta.","13":"dxc3 — adversarul schimbă pionul.","14":"Db3 — înainte să iei înapoi, dama atacă pionul de pe f7, împreună cu nebunul.","15":"De7 — adversarul apără f7 cu dama.","16":"Cxc3 — iei înapoi pionul şi îţi dezvolţi calul."},"final_text":"Ai aproape toate piesele în joc, iar adversarul a scos doar calul şi dama. Planul: Ng5, apoi tura în centru.","popularitate_niveluri":{"incepator":22.9,"intermediar":13.7,"avansat":8.3}},{"nume":"Dacă adversarul joacă 6…c5","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 c6d4 f3d4 e5d4 e1g1 d7d6 c2c3 c7c5 c3d4 c5d4 d2d3 g8f6 d1b3 d8e7 c1g5","move_explanations":{"11":"c5 — adversarul îşi sprijină pionul de pe d4 cu încă un pion.","12":"cxd4 — iei pionul.","13":"cxd4 — adversarul ia înapoi.","14":"d3 — fixezi pionul de pe d4 şi îţi deschizi nebunul de pe c1.","15":"Cf6 — adversarul scoate calul.","16":"Db3 — dama atacă pionul de pe f7, împreună cu nebunul.","17":"De7 — adversarul apără f7 cu dama.","18":"Ng5 — legi calul de pe f6 de damă."},"final_text":"Calul de pe f6 e legat de damă, iar adversarul încă nu şi-a scos nebunul de pe f8. Ai mai multe piese în joc: urmează Cd2 şi tura pe coloana c.","popularitate_niveluri":{"incepator":11.3,"intermediar":13,"avansat":10.3}}]$j$::jsonb
  from public.courses c where c.id = l.course_id and c.slug = 'italian-game' and l.variation_code = 'P3';

do $$
declare n int; total int;
begin
  select count(*), coalesce(sum(jsonb_array_length(l.variante)), 0) into n, total
    from public.opening_lines l join public.courses c on c.id = l.course_id
   where c.slug = 'italian-game' and l.variante is not null;
  if n <> 8 or total <> 23 then
    raise exception 'Italiana: % capitole cu variante, % variante; aşteptat 8 şi 23', n, total;
  end if;
end $$;
